/*
 * Imitation of a CleverTap-style web SDK, written for Khara Check's practice site. It is not CleverTap's code.
 * Each event is wrapped in JSON, base64-encoded, and posted inside another JSON document.
 */
(function () {
  var account = (window.clevertap.account[0] || {}).id;
  var guid = 'g' + Math.random().toString(16).slice(2);
  function send(name, data) {
    var event = { type: 'event', evtName: name, evtData: data, g: guid, pg: 1, ts: Math.floor(Date.now() / 1000) };
    var d = btoa(unescape(encodeURIComponent(JSON.stringify(event))));
    fetch('https://in1.clevertap-prod.com/a?t=96&type=push&id=' + encodeURIComponent(account), {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ d: d, id: account, sn: 'web' }),
      keepalive: true
    }).catch(function () {});
  }
  var queued = window.clevertap.event;
  window.clevertap.event = { push: function (name, data) { send(name, data || {}); } };
  for (var i = 0; i + 1 < queued.length; i += 2) send(queued[i], queued[i + 1]);
})();
